import{_ as e,o,c as l,a2 as t}from"./chunks/framework.C0KMm31j.js";const i="/Nav2ArticlesSite/article-assets/2026-07-17/nav2_regulated_no_bt_cover.png",n="/Nav2ArticlesSite/article-assets/2026-07-17/nav2_regulated_no_bt_01_topology.png",c="/Nav2ArticlesSite/article-assets/2026-07-17/nav2_regulated_no_bt_02_interfaces.png",s="/Nav2ArticlesSite/article-assets/2026-07-17/nav2_regulated_no_bt_03_state_machine.png",r="/Nav2ArticlesSite/article-assets/2026-07-17/nav2_regulated_no_bt_04_sequence.png",d="/Nav2ArticlesSite/article-assets/2026-07-17/nav2_regulated_no_bt_05_async_guard.png",p="/Nav2ArticlesSite/article-assets/2026-07-17/nav2_regulated_no_bt_06_safety_recovery.png",f=JSON.parse('{"title":"砍掉行为树之后，Nav2 还能怎么跑？一套自研规控导航的状态机与全数据流拆解","description":"Nav2 的默认导航入口是 btnavigator：它读取行为树 XML，再把规划、控制、恢复行为组织成一棵运行时任务树。","frontmatter":{"title":"砍掉行为树之后，Nav2 还能怎么跑？一套自研规控导航的状态机与全数据流拆解","description":"Nav2 的默认导航入口是 btnavigator：它读取行为树 XML，再把规划、控制、恢复行为组织成一棵运行时任务树。","date":"2026-07-17","section":"一 · 架构与启动","readingTime":13,"source":"2026-07-17/nav2_regulated_no_bt_full_dataflow.md","status":"published","cover":"/article-assets/2026-07-17/nav2_regulated_no_bt_cover.png","head":[["link",{"rel":"canonical","href":"https://zpy560.github.io/Nav2ArticlesSite/nav2/nav2-regulated-no-bt-full-dataflow"}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:title","content":"砍掉行为树之后，Nav2 还能怎么跑？一套自研规控导航的状态机与全数据流拆解"}],["meta",{"property":"og:description","content":"Nav2 的默认导航入口是 btnavigator：它读取行为树 XML，再把规划、控制、恢复行为组织成一棵运行时任务树。"}],["meta",{"property":"og:url","content":"https://zpy560.github.io/Nav2ArticlesSite/nav2/nav2-regulated-no-bt-full-dataflow"}],["meta",{"property":"og:image","content":"https://zpy560.github.io/Nav2ArticlesSite/article-assets/2026-07-17/nav2_regulated_no_bt_cover.png"}],["meta",{"property":"article:published_time","content":"2026-07-17"}],["meta",{"name":"twitter:title","content":"砍掉行为树之后，Nav2 还能怎么跑？一套自研规控导航的状态机与全数据流拆解"}],["meta",{"name":"twitter:description","content":"Nav2 的默认导航入口是 btnavigator：它读取行为树 XML，再把规划、控制、恢复行为组织成一棵运行时任务树。"}],["meta",{"name":"twitter:image","content":"https://zpy560.github.io/Nav2ArticlesSite/article-assets/2026-07-17/nav2_regulated_no_bt_cover.png"}]],"prev":{"text":"Nav2 的两张地图怎样驱动规划与控制？全局与局部 Costmap 全数据流拆解","link":"/nav2/nav2-global-local-map-full-dataflow"},"next":{"text":"一个节点失联，为什么整套 Nav2 都要停？逐函数拆解 Lifecycle Manager","link":"/nav2/nav2-lifecycle-manager-source-walkthrough"}},"headers":[],"relativePath":"nav2/nav2-regulated-no-bt-full-dataflow.md","filePath":"nav2/nav2-regulated-no-bt-full-dataflow.md","lastUpdated":null}'),h={name:"nav2/nav2-regulated-no-bt-full-dataflow.md"};function _(u,a,m,g,v,b){return o(),l("div",null,[...a[0]||(a[0]=[t('<h1 id="砍掉行为树之后-nav2-还能怎么跑-一套自研规控导航的状态机与全数据流拆解" tabindex="-1">砍掉行为树之后，Nav2 还能怎么跑？一套自研规控导航的状态机与全数据流拆解 <a class="header-anchor" href="#砍掉行为树之后-nav2-还能怎么跑-一套自研规控导航的状态机与全数据流拆解" aria-label="Permalink to &quot;砍掉行为树之后，Nav2 还能怎么跑？一套自研规控导航的状态机与全数据流拆解&quot;">​</a></h1><p><img src="'+i+'" alt="封面：无行为树 Nav2 自研规控导航"></p><p>Nav2 的默认导航入口是 <code>bt_navigator</code>：它读取行为树 XML，再把规划、控制、恢复行为组织成一棵运行时任务树。</p><p>但行为树不是 Nav2 规划器和控制器运行的必要条件。真正执行路径搜索、路径平滑、轨迹跟踪和速度约束的，仍然是 Planner Server、Smoother Server、Controller Server 与 Velocity Smoother。</p><p>本文拆解的 <code>nav2_regulated_modules</code> 做了一件很直接的事：</p><blockquote><p>删除 <code>bt_navigator</code>、<code>behavior_server</code> 和 <code>waypoint_follower</code>，保留 Nav2 规划控制主链，用一个显式 C++ 状态机重新实现目标接入、Action 编排、周期重规划、定位保护、取消抢占和轻量自恢复。</p></blockquote><p>它不是“把 Nav2 全部推倒重写”，而是替换 Nav2 的任务编排层。</p><p><img src="'+n+`" alt="图 1：无行为树规控导航运行拓扑"></p><h2 id="一、先给结论-被替换的是编排层-不是规划控制算法" tabindex="-1">一、先给结论：被替换的是编排层，不是规划控制算法 <a class="header-anchor" href="#一、先给结论-被替换的是编排层-不是规划控制算法" aria-label="Permalink to &quot;一、先给结论：被替换的是编排层，不是规划控制算法&quot;">​</a></h2><p>这个包启动的导航主链是：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>目标输入</span></span>
<span class="line"><span>  ↓</span></span>
<span class="line"><span>regulated_navigator</span></span>
<span class="line"><span>  ↓ ComputePathToPose／ComputePathThroughPoses</span></span>
<span class="line"><span>planner_server</span></span>
<span class="line"><span>  ↓ Path</span></span>
<span class="line"><span>smoother_server</span></span>
<span class="line"><span>  ↓ SmoothPath</span></span>
<span class="line"><span>controller_server</span></span>
<span class="line"><span>  ↓ cmd_vel_nav</span></span>
<span class="line"><span>velocity_smoother</span></span>
<span class="line"><span>  ↓ cmd_vel</span></span>
<span class="line"><span>controlpub</span></span>
<span class="line"><span>  ↓</span></span>
<span class="line"><span>/control_to_uart</span></span></code></pre></div><h3 id="_1-1-保留的模块" tabindex="-1">1.1 保留的模块 <a class="header-anchor" href="#_1-1-保留的模块" aria-label="Permalink to &quot;1.1 保留的模块&quot;">​</a></h3><ul><li><code>map_server</code>：发布静态地图。</li><li>Global Costmap：供全局规划使用。</li><li>Local Costmap：供局部控制使用。</li><li><code>planner_server</code>：加载 NavFn、SMAC、Theta* 等全局规划插件。</li><li><code>smoother_server</code>：提供路径平滑。</li><li><code>controller_server</code>：加载 DWB、RPP、MPPI 等控制插件。</li><li><code>velocity_smoother</code>：对速度做限幅和加减速平滑。</li><li>Lifecycle Manager：按依赖顺序激活和停用节点。</li></ul><h3 id="_1-2-不启动的模块" tabindex="-1">1.2 不启动的模块 <a class="header-anchor" href="#_1-2-不启动的模块" aria-label="Permalink to &quot;1.2 不启动的模块&quot;">​</a></h3><ul><li><code>bt_navigator</code>。</li><li><code>behavior_server</code>。</li><li><code>waypoint_follower</code>。</li><li>AMCL。</li></ul><h3 id="_1-3-轻量恢复边界" tabindex="-1">1.3 轻量恢复边界 <a class="header-anchor" href="#_1-3-轻量恢复边界" aria-label="Permalink to &quot;1.3 轻量恢复边界&quot;">​</a></h3><p>不启动 <code>behavior_server</code>，不等于任何异常处理都被删除。当前自研节点没有 Spin、BackUp、Wait 等 Nav2 Behavior Action，但仍保留“停车、清理双 Costmap、等待地图更新、重新规划”的轻量自恢复。</p><h2 id="二、启动文件怎样构造整套系统" tabindex="-1">二、启动文件怎样构造整套系统 <a class="header-anchor" href="#二、启动文件怎样构造整套系统" aria-label="Permalink to &quot;二、启动文件怎样构造整套系统&quot;">​</a></h2><p><code>regulated_modules.launch.py</code> 把系统分成两组 Lifecycle。</p><h3 id="_2-1-地图服务-lifecycle-组" tabindex="-1">2.1 地图服务 Lifecycle 组 <a class="header-anchor" href="#_2-1-地图服务-lifecycle-组" aria-label="Permalink to &quot;2.1 地图服务 Lifecycle 组&quot;">​</a></h3><p>只管理 <code>map_server</code>，由 <code>lifecycle_manager_localization</code> 激活。</p><h3 id="_2-2-规控-lifecycle-组" tabindex="-1">2.2 规控 Lifecycle 组 <a class="header-anchor" href="#_2-2-规控-lifecycle-组" aria-label="Permalink to &quot;2.2 规控 Lifecycle 组&quot;">​</a></h3><p>按顺序管理：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>planner_server</span></span>
<span class="line"><span>controller_server</span></span>
<span class="line"><span>smoother_server</span></span>
<span class="line"><span>velocity_smoother</span></span>
<span class="line"><span>regulated_navigator</span></span></code></pre></div><p><code>regulated_navigator</code> 放在最后激活，因为它一旦接收目标，就会立即等待规划、平滑和控制 Action Server。停机时顺序相反，规控入口先停止，避免下游服务器退出后仍接收新任务。</p><h3 id="_2-3-进程部署方式" tabindex="-1">2.3 进程部署方式 <a class="header-anchor" href="#_2-3-进程部署方式" aria-label="Permalink to &quot;2.3 进程部署方式&quot;">​</a></h3><p>非组合模式下，各服务器是独立进程；组合模式下，Planner、Controller、Smoother、Velocity Smoother 和 Lifecycle Manager 可以装入组件容器，但自研 <code>regulated_navigator</code> 与 <code>controlpub</code> 仍作为普通节点启动。</p><h2 id="三、所有输入输出-一张图看清数据从哪里来、到哪里去" tabindex="-1">三、所有输入输出：一张图看清数据从哪里来、到哪里去 <a class="header-anchor" href="#三、所有输入输出-一张图看清数据从哪里来、到哪里去" aria-label="Permalink to &quot;三、所有输入输出：一张图看清数据从哪里来、到哪里去&quot;">​</a></h2><p><img src="`+c+'" alt="图 2：规控导航全部输入输出数据流"></p><h3 id="_3-1-外部目标输入" tabindex="-1">3.1 外部目标输入 <a class="header-anchor" href="#_3-1-外部目标输入" aria-label="Permalink to &quot;3.1 外部目标输入&quot;">​</a></h3><h4 id="_3-1-1-navigate-to-pose" tabindex="-1">3.1.1 <code>/navigate_to_pose</code> <a class="header-anchor" href="#_3-1-1-navigate-to-pose" aria-label="Permalink to &quot;3.1.1 `/navigate_to_pose`&quot;">​</a></h4><ul><li>类型：<code>nav2_msgs/action/NavigateToPose</code>。</li><li>方向：外部客户端调用 <code>regulated_navigator</code>。</li><li>作用：提交单个目标位姿，并接收当前位置、剩余距离、预计时间和恢复次数反馈。</li><li>约束：<code>behavior_tree</code> 字段必须为空；传入 XML 会被明确拒绝。</li></ul><h4 id="_3-1-2-navigate-through-poses" tabindex="-1">3.1.2 <code>/navigate_through_poses</code> <a class="header-anchor" href="#_3-1-2-navigate-through-poses" aria-label="Permalink to &quot;3.1.2 `/navigate_through_poses`&quot;">​</a></h4><ul><li>类型：<code>nav2_msgs/action/NavigateThroughPoses</code>。</li><li>方向：外部客户端调用 <code>regulated_navigator</code>。</li><li>作用：提交一组连续目标位姿。</li><li>特有反馈：除通用导航反馈外，还返回剩余目标点数量。</li></ul><h4 id="_3-1-3-goal-pose" tabindex="-1">3.1.3 <code>/goal_pose</code> <a class="header-anchor" href="#_3-1-3-goal-pose" aria-label="Permalink to &quot;3.1.3 `/goal_pose`&quot;">​</a></h4><ul><li>类型：<code>geometry_msgs/msg/PoseStamped</code>。</li><li>方向：RViz 或简单上层节点发布给 <code>regulated_navigator</code>。</li><li>作用：提供不需要 Action 结果的兼容单点入口。</li><li>行为：新 Topic 目标同样采用替换式抢占，但没有外层 Action 反馈和结果。</li></ul><p>所有目标都必须包含有效 <code>frame_id</code>、有限数值的位置和非零范数四元数。</p><h3 id="_3-2-自研定位输入" tabindex="-1">3.2 自研定位输入 <a class="header-anchor" href="#_3-2-自研定位输入" aria-label="Permalink to &quot;3.2 自研定位输入&quot;">​</a></h3><h4 id="_3-2-1-map-base-link" tabindex="-1">3.2.1 <code>map -&gt; base_link</code> <a class="header-anchor" href="#_3-2-1-map-base-link" aria-label="Permalink to &quot;3.2.1 `map -&gt; base_link`&quot;">​</a></h4><ul><li>类型：TF 动态变换。</li><li>方向：外部自研定位系统提供给规控节点和两张 Costmap。</li><li>作用：获取当前位姿、生成导航反馈、判断定位超时和跳变、计算是否有真实运动进展。</li><li>关键点：本方案不依赖 <code>map -&gt; odom -&gt; base_link</code>，也不读取里程计消息判断规控进展。</li></ul><h3 id="_3-3-地图和传感器输入" tabindex="-1">3.3 地图和传感器输入 <a class="header-anchor" href="#_3-3-地图和传感器输入" aria-label="Permalink to &quot;3.3 地图和传感器输入&quot;">​</a></h3><h4 id="_3-3-1-地图-yaml-pgm" tabindex="-1">3.3.1 地图 YAML／PGM <a class="header-anchor" href="#_3-3-1-地图-yaml-pgm" aria-label="Permalink to &quot;3.3.1 地图 YAML／PGM&quot;">​</a></h4><ul><li>消费者：<code>map_server</code>。</li><li>输出：<code>/map</code>，类型为 <code>nav_msgs/msg/OccupancyGrid</code>。</li><li>下游：Global Costmap 的 Static Layer。</li></ul><h4 id="_3-3-2-c200-lidar-node1-scan" tabindex="-1">3.3.2 <code>/c200_lidar_node1/scan</code> <a class="header-anchor" href="#_3-3-2-c200-lidar-node1-scan" aria-label="Permalink to &quot;3.3.2 `/c200_lidar_node1/scan`&quot;">​</a></h4><ul><li>类型：<code>sensor_msgs/msg/LaserScan</code>。</li><li>消费者：Global Costmap 的 Obstacle Layer、Local Costmap 的 Voxel Layer。</li><li>作用：同时参与全局动态绕障和局部实时避障。</li></ul><h3 id="_3-4-路径与控制输出" tabindex="-1">3.4 路径与控制输出 <a class="header-anchor" href="#_3-4-路径与控制输出" aria-label="Permalink to &quot;3.4 路径与控制输出&quot;">​</a></h3><h4 id="_3-4-1-plan" tabindex="-1">3.4.1 <code>/plan</code> <a class="header-anchor" href="#_3-4-1-plan" aria-label="Permalink to &quot;3.4.1 `/plan`&quot;">​</a></h4><ul><li>类型：<code>nav_msgs/msg/Path</code>。</li><li>发布者：Planner Server。</li><li>作用：全局路径可视化和调试。</li></ul><h4 id="_3-4-2-cmd-vel-nav" tabindex="-1">3.4.2 <code>/cmd_vel_nav</code> <a class="header-anchor" href="#_3-4-2-cmd-vel-nav" aria-label="Permalink to &quot;3.4.2 `/cmd_vel_nav`&quot;">​</a></h4><ul><li>类型：<code>geometry_msgs/msg/Twist</code>。</li><li>发布者：Controller Server，也可能由规控节点连续发布三帧零速度。</li><li>消费者：Velocity Smoother。</li></ul><h4 id="_3-4-3-cmd-vel" tabindex="-1">3.4.3 <code>/cmd_vel</code> <a class="header-anchor" href="#_3-4-3-cmd-vel" aria-label="Permalink to &quot;3.4.3 `/cmd_vel`&quot;">​</a></h4><ul><li>类型：<code>geometry_msgs/msg/Twist</code>。</li><li>发布者：Velocity Smoother。</li><li>消费者：<code>controlpub</code>。</li></ul><h4 id="_3-4-4-control-to-uart" tabindex="-1">3.4.4 <code>/control_to_uart</code> <a class="header-anchor" href="#_3-4-4-control-to-uart" aria-label="Permalink to &quot;3.4.4 `/control_to_uart`&quot;">​</a></h4><ul><li>发布者：<code>controlpub</code>。</li><li>作用：把平滑后的速度转换为底盘串口控制链所需数据。</li></ul><h3 id="_3-5-规控节点调用的内部-action-和-service" tabindex="-1">3.5 规控节点调用的内部 Action 和 Service <a class="header-anchor" href="#_3-5-规控节点调用的内部-action-和-service" aria-label="Permalink to &quot;3.5 规控节点调用的内部 Action 和 Service&quot;">​</a></h3><h4 id="_3-5-1-compute-path-to-pose" tabindex="-1">3.5.1 <code>/compute_path_to_pose</code> <a class="header-anchor" href="#_3-5-1-compute-path-to-pose" aria-label="Permalink to &quot;3.5.1 `/compute_path_to_pose`&quot;">​</a></h4><ul><li>类型：<code>nav2_msgs/action/ComputePathToPose</code>。</li><li>服务端：Planner Server。</li><li>请求核心字段：单目标、<code>planner_id</code>、是否使用指定起点。</li><li>返回核心数据：<code>nav_msgs/msg/Path</code> 和规划时间。</li></ul><h4 id="_3-5-2-compute-path-through-poses" tabindex="-1">3.5.2 <code>/compute_path_through_poses</code> <a class="header-anchor" href="#_3-5-2-compute-path-through-poses" aria-label="Permalink to &quot;3.5.2 `/compute_path_through_poses`&quot;">​</a></h4><ul><li>类型：<code>nav2_msgs/action/ComputePathThroughPoses</code>。</li><li>服务端：Planner Server。</li><li>请求核心字段：剩余目标数组和 <code>planner_id</code>。</li><li>返回核心数据：贯穿多个目标的 Path。</li></ul><h4 id="_3-5-3-smooth-path" tabindex="-1">3.5.3 <code>/smooth_path</code> <a class="header-anchor" href="#_3-5-3-smooth-path" aria-label="Permalink to &quot;3.5.3 `/smooth_path`&quot;">​</a></h4><ul><li>类型：<code>nav2_msgs/action/SmoothPath</code>。</li><li>服务端：Smoother Server。</li><li>请求核心字段：原始 Path、<code>smoother_id</code>、最大平滑时间、是否检查碰撞。</li><li>返回核心数据：平滑 Path。</li></ul><h4 id="_3-5-4-follow-path" tabindex="-1">3.5.4 <code>/follow_path</code> <a class="header-anchor" href="#_3-5-4-follow-path" aria-label="Permalink to &quot;3.5.4 `/follow_path`&quot;">​</a></h4><ul><li>类型：<code>nav2_msgs/action/FollowPath</code>。</li><li>服务端：Controller Server。</li><li>请求核心字段：Path、<code>controller_id</code>、<code>goal_checker_id</code>。</li><li>反馈核心数据：剩余距离和当前速度。</li></ul><h4 id="_3-5-5-local-costmap-clear-entirely-local-costmap" tabindex="-1">3.5.5 <code>/local_costmap/clear_entirely_local_costmap</code> <a class="header-anchor" href="#_3-5-5-local-costmap-clear-entirely-local-costmap" aria-label="Permalink to &quot;3.5.5 `/local_costmap/clear_entirely_local_costmap`&quot;">​</a></h4><ul><li>类型：<code>nav2_msgs/srv/ClearEntireCostmap</code>。</li><li>调用时机：轻量恢复。</li><li>作用：清空 Local Costmap，随后由激光观测重新填充动态障碍。</li></ul><h4 id="_3-5-6-global-costmap-clear-entirely-global-costmap" tabindex="-1">3.5.6 <code>/global_costmap/clear_entirely_global_costmap</code> <a class="header-anchor" href="#_3-5-6-global-costmap-clear-entirely-global-costmap" aria-label="Permalink to &quot;3.5.6 `/global_costmap/clear_entirely_global_costmap`&quot;">​</a></h4><ul><li>类型：<code>nav2_msgs/srv/ClearEntireCostmap</code>。</li><li>调用时机：轻量恢复。</li><li>作用：清空 Global Costmap，再由静态地图层和激光层重新融合。</li></ul><h3 id="_3-6-地图、可视化和生命周期接口" tabindex="-1">3.6 地图、可视化和生命周期接口 <a class="header-anchor" href="#_3-6-地图、可视化和生命周期接口" aria-label="Permalink to &quot;3.6 地图、可视化和生命周期接口&quot;">​</a></h3><h4 id="_3-6-1-map-与-map-server-service" tabindex="-1">3.6.1 <code>/map</code> 与 Map Server Service <a class="header-anchor" href="#_3-6-1-map-与-map-server-service" aria-label="Permalink to &quot;3.6.1 `/map` 与 Map Server Service&quot;">​</a></h4><ul><li><code>/map</code>：<code>nav_msgs/msg/OccupancyGrid</code>，为 Global Costmap 提供静态底图。</li><li><code>/map_server/map</code>：<code>nav_msgs/srv/GetMap</code>，供外部主动读取当前地图。</li><li><code>/map_server/load_map</code>：<code>nav2_msgs/srv/LoadMap</code>，运行时加载新地图。</li></ul><h4 id="_3-6-2-costmap-调试输出" tabindex="-1">3.6.2 Costmap 调试输出 <a class="header-anchor" href="#_3-6-2-costmap-调试输出" aria-label="Permalink to &quot;3.6.2 Costmap 调试输出&quot;">​</a></h4><ul><li><code>/global_costmap/costmap</code>：全局主代价地图。</li><li><code>/local_costmap/costmap</code>：局部主代价地图。</li><li><code>/local_costmap/voxel_grid</code>：局部 Voxel Layer 的体素调试数据。</li><li>这些 Topic 主要供 RViz 和诊断工具使用；Planner 和 Controller 在各自进程内直接读取 Costmap 对象。</li></ul><h4 id="_3-6-3-tf-与-tf-static" tabindex="-1">3.6.3 <code>/tf</code> 与 <code>/tf_static</code> <a class="header-anchor" href="#_3-6-3-tf-与-tf-static" aria-label="Permalink to &quot;3.6.3 `/tf` 与 `/tf_static`&quot;">​</a></h4><ul><li>Launch 支持命名空间重映射。</li><li>当前规控主链只要求动态 <code>map -&gt; base_link</code>；测试激光的 <code>frame_id</code> 直接为 <code>base_link</code>。</li></ul><h4 id="_3-6-4-lifecycle-接口" tabindex="-1">3.6.4 Lifecycle 接口 <a class="header-anchor" href="#_3-6-4-lifecycle-接口" aria-label="Permalink to &quot;3.6.4 Lifecycle 接口&quot;">​</a></h4><ul><li><code>map_server</code> 由独立 Lifecycle Manager 管理。</li><li>Planner、Controller、Smoother、Velocity Smoother 和 <code>regulated_navigator</code> 由规控 Lifecycle Manager 管理。</li><li>每个 Lifecycle 节点仍暴露标准 <code>change_state</code>、<code>get_state</code> 等 Service；Manager 通过状态转换和 Bond 监控完成自动拉起与故障检测。</li></ul><h2 id="四、10-个状态怎样替代一棵行为树" tabindex="-1">四、10 个状态怎样替代一棵行为树 <a class="header-anchor" href="#四、10-个状态怎样替代一棵行为树" aria-label="Permalink to &quot;四、10 个状态怎样替代一棵行为树&quot;">​</a></h2><p>行为树把执行状态隐藏在树节点、黑板和 Tick 流程里；当前实现则把任务阶段写成一个显式枚举。</p><p><img src="'+s+'" alt="图 3：自研规控导航完整状态机"></p><h3 id="_4-1-idle" tabindex="-1">4.1 <code>IDLE</code> <a class="header-anchor" href="#_4-1-idle" aria-label="Permalink to &quot;4.1 `IDLE`&quot;">​</a></h3><p>没有活动任务。新目标到来后创建 <code>NavigationTask</code>，分配新的 generation，再进入规划。</p><h3 id="_4-2-planning" tabindex="-1">4.2 <code>PLANNING</code> <a class="header-anchor" href="#_4-2-planning" aria-label="Permalink to &quot;4.2 `PLANNING`&quot;">​</a></h3><p>首次请求全局路径。单点任务调用 <code>ComputePathToPose</code>，多点任务调用 <code>ComputePathThroughPoses</code>。</p><h3 id="_4-3-smoothing" tabindex="-1">4.3 <code>SMOOTHING</code> <a class="header-anchor" href="#_4-3-smoothing" aria-label="Permalink to &quot;4.3 `SMOOTHING`&quot;">​</a></h3><p>规划成功且 <code>use_smoother=true</code> 时调用 <code>SmoothPath</code>。如果平滑 Goal 被拒绝、执行失败或返回空路径，不直接终止任务，而是回退使用原始规划路径。</p><h3 id="_4-4-controlling" tabindex="-1">4.4 <code>CONTROLLING</code> <a class="header-anchor" href="#_4-4-controlling" aria-label="Permalink to &quot;4.4 `CONTROLLING`&quot;">​</a></h3><p>向 Controller Server 发送 <code>FollowPath</code>。规控节点从 FollowPath 反馈中读取：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>distance_to_goal</span></span>\n<span class="line"><span>speed</span></span></code></pre></div><p>再结合 TF 生成对外导航反馈。</p><h3 id="_4-5-replanning" tabindex="-1">4.5 <code>REPLANNING</code> <a class="header-anchor" href="#_4-5-replanning" aria-label="Permalink to &quot;4.5 `REPLANNING`&quot;">​</a></h3><p>控制过程中按 <code>replan_frequency</code> 周期重新计算路径。重规划不先停止当前控制；新路径准备完成后，再用新的 FollowPath Goal 替换旧路径。</p><p>如果后台重规划暂时失败，但旧 FollowPath 仍有效，并且连续失败未达到上限，状态回到 <code>CONTROLLING</code>，继续沿旧路径运动。</p><h3 id="_4-6-clearing-costmap" tabindex="-1">4.6 <code>CLEARING_COSTMAP</code> <a class="header-anchor" href="#_4-6-clearing-costmap" aria-label="Permalink to &quot;4.6 `CLEARING_COSTMAP`&quot;">​</a></h3><p>规划或控制失败、长时间无位移时进入轻量恢复：取消下游 Goal、停车、调用两张 Costmap 的完整清理 Service，等待配置时间后重新规划。</p><h3 id="_4-7-localization-lost" tabindex="-1">4.7 <code>LOCALIZATION_LOST</code> <a class="header-anchor" href="#_4-7-localization-lost" aria-label="Permalink to &quot;4.7 `LOCALIZATION_LOST`&quot;">​</a></h3><p>超过 <code>localization_timeout</code> 无法获得 <code>map -&gt; base_link</code> 后，立即取消控制并停车。定位恢复后必须连续稳定达到 <code>localization_stable_duration</code>，才重新规划。</p><h3 id="_4-8-canceling" tabindex="-1">4.8 <code>CANCELING</code> <a class="header-anchor" href="#_4-8-canceling" aria-label="Permalink to &quot;4.8 `CANCELING`&quot;">​</a></h3><p>外层客户端请求取消时进入。规控节点取消规划、平滑和控制子 Goal，发送零速度，并把外层 Action 标记为 canceled。</p><h3 id="_4-9-succeeded" tabindex="-1">4.9 <code>SUCCEEDED</code> <a class="header-anchor" href="#_4-9-succeeded" aria-label="Permalink to &quot;4.9 `SUCCEEDED`&quot;">​</a></h3><p>FollowPath 成功后，结束对应的单点或多点 Action，再重置为 <code>IDLE</code>。</p><h3 id="_4-10-failed" tabindex="-1">4.10 <code>FAILED</code> <a class="header-anchor" href="#_4-10-failed" aria-label="Permalink to &quot;4.10 `FAILED`&quot;">​</a></h3><p>依赖服务器不可用、恢复次数耗尽或定位恢复超时后进入。外层 Action 返回 abort，任务随后重置。</p><h2 id="五、一个单点目标到底经过了哪些调用" tabindex="-1">五、一个单点目标到底经过了哪些调用 <a class="header-anchor" href="#五、一个单点目标到底经过了哪些调用" aria-label="Permalink to &quot;五、一个单点目标到底经过了哪些调用&quot;">​</a></h2><p><img src="'+r+`" alt="图 4：NavigateToPose 完整 Action 时序"></p><p>一次正常单点导航可以拆成八步。</p><h3 id="_5-1-接收并校验目标" tabindex="-1">5.1 接收并校验目标 <a class="header-anchor" href="#_5-1-接收并校验目标" aria-label="Permalink to &quot;5.1 接收并校验目标&quot;">​</a></h3><p>节点只有处于 Lifecycle Active 时才接受目标。目标无 frame、包含非法浮点数、四元数无效或携带行为树 XML，都会在 Action Goal 阶段被拒绝。</p><h3 id="_5-2-替换旧任务" tabindex="-1">5.2 替换旧任务 <a class="header-anchor" href="#_5-2-替换旧任务" aria-label="Permalink to &quot;5.2 替换旧任务&quot;">​</a></h3><p>当前若已有任务，新目标采用 replace 策略：旧的规划、平滑和控制 Goal 全部取消；旧外层 Action 返回 abort；机器人收到零速度。</p><h3 id="_5-3-等待依赖" tabindex="-1">5.3 等待依赖 <a class="header-anchor" href="#_5-3-等待依赖" aria-label="Permalink to &quot;5.3 等待依赖&quot;">​</a></h3><p>规控节点确认以下 Action Server 可用：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>compute_path_to_pose</span></span>
<span class="line"><span>compute_path_through_poses</span></span>
<span class="line"><span>smooth_path（启用时）</span></span>
<span class="line"><span>follow_path</span></span></code></pre></div><p>任一依赖在 <code>server_timeout</code> 内不可用，任务直接失败。</p><h3 id="_5-4-计算路径" tabindex="-1">5.4 计算路径 <a class="header-anchor" href="#_5-4-计算路径" aria-label="Permalink to &quot;5.4 计算路径&quot;">​</a></h3><p>规控节点向 Planner Server 发送目标和 <code>planner_id</code>。<code>use_start=false</code>，意味着 Planner Server 根据 TF 获取当前机器人起点。</p><h3 id="_5-5-平滑或回退" tabindex="-1">5.5 平滑或回退 <a class="header-anchor" href="#_5-5-平滑或回退" aria-label="Permalink to &quot;5.5 平滑或回退&quot;">​</a></h3><p>原始 Path 被保存到 <code>pending_raw_path_</code>。平滑成功则使用平滑 Path；失败则使用原始 Path，避免平滑器成为单点故障源。</p><h3 id="_5-6-跟随路径" tabindex="-1">5.6 跟随路径 <a class="header-anchor" href="#_5-6-跟随路径" aria-label="Permalink to &quot;5.6 跟随路径&quot;">​</a></h3><p>规控节点向 Controller Server 发送：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>path</span></span>
<span class="line"><span>controller_id</span></span>
<span class="line"><span>goal_checker_id</span></span></code></pre></div><p>Controller 读取 Local Costmap，以配置频率输出 <code>/cmd_vel_nav</code>。</p><h3 id="_5-7-周期监控和重规划" tabindex="-1">5.7 周期监控和重规划 <a class="header-anchor" href="#_5-7-周期监控和重规划" aria-label="Permalink to &quot;5.7 周期监控和重规划&quot;">​</a></h3><p>200 ms 监控定时器检查 TF、定位跳变、真实位移进展、多点通过情况和重规划时间；反馈定时器按 <code>feedback_frequency</code> 向外层 Action 发布反馈。</p><h3 id="_5-8-结果收口" tabindex="-1">5.8 结果收口 <a class="header-anchor" href="#_5-8-结果收口" aria-label="Permalink to &quot;5.8 结果收口&quot;">​</a></h3><p>FollowPath 成功则外层导航成功；失败则进入轻量恢复；取消或抢占则所有旧回调失效并停车。</p><h2 id="六、多点任务不是-waypoint-follower" tabindex="-1">六、多点任务不是 Waypoint Follower <a class="header-anchor" href="#六、多点任务不是-waypoint-follower" aria-label="Permalink to &quot;六、多点任务不是 Waypoint Follower&quot;">​</a></h2><p>多点入口沿用标准 <code>NavigateThroughPoses</code>，但实现不依赖 <code>waypoint_follower</code> 插件。</p><p>规控节点把剩余目标数组整体发送给 <code>ComputePathThroughPoses</code>。监控阶段通过当前 TF 与第一个目标的平面距离判断是否通过中间点：距离小于 <code>passed_goal_radius</code> 时，从数组头部删除该点，但至少保留最后一个终点。</p><p>这意味着它提供的是“沿一条连续路径经过多个位姿”，而不是 Waypoint Follower 那种“到点后执行拍照、等待或自定义插件任务”。</p><h2 id="七、异步-action-最危险的问题-旧回调覆盖新任务" tabindex="-1">七、异步 Action 最危险的问题：旧回调覆盖新任务 <a class="header-anchor" href="#七、异步-action-最危险的问题-旧回调覆盖新任务" aria-label="Permalink to &quot;七、异步 Action 最危险的问题：旧回调覆盖新任务&quot;">​</a></h2><p>ROS 2 Action 是异步的。一个旧规划请求可能在新目标已经开始后才返回；如果直接接收结果，旧路径就会覆盖新路径。</p><p><img src="`+d+`" alt="图 5：generation 与 sequence 如何隔离过期回调"></p><p>当前实现使用三层标识：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>task_generation</span></span>
<span class="line"><span>plan_sequence</span></span>
<span class="line"><span>follow_sequence</span></span></code></pre></div><p><code>generation</code> 区分整个导航任务；两个 <code>sequence</code> 分别区分同一任务中的多次规划和多次 FollowPath。</p><p>每个 Action 回调都捕获发送时的 generation 和 sequence，执行前重新比较：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>回调 generation == 当前任务 generation</span></span>
<span class="line"><span>并且</span></span>
<span class="line"><span>回调 sequence == 当前阶段 sequence</span></span></code></pre></div><p>取消、抢占、恢复和重新下发路径都会递增相应序号。旧回调即使迟到，也只会被忽略，不能再修改当前状态。</p><p>这套机制承担了行为树 Halt、节点状态和黑板任务隔离的一部分职责，也是自研异步编排最不能省略的安全边界。</p><h2 id="八、没有-behavior-server-后-异常怎样处理" tabindex="-1">八、没有 Behavior Server 后，异常怎样处理 <a class="header-anchor" href="#八、没有-behavior-server-后-异常怎样处理" aria-label="Permalink to &quot;八、没有 Behavior Server 后，异常怎样处理&quot;">​</a></h2><p><img src="`+p+'" alt="图 6：定位保护、轻量恢复与停车数据流"></p><h3 id="_8-1-规划失败" tabindex="-1">8.1 规划失败 <a class="header-anchor" href="#_8-1-规划失败" aria-label="Permalink to &quot;8.1 规划失败&quot;">​</a></h3><p>首次规划失败会进入恢复。周期重规划失败时，只要旧 FollowPath 仍在执行且连续失败次数未达到阈值，就继续使用旧路径。</p><h3 id="_8-2-控制失败或无进展" tabindex="-1">8.2 控制失败或无进展 <a class="header-anchor" href="#_8-2-控制失败或无进展" aria-label="Permalink to &quot;8.2 控制失败或无进展&quot;">​</a></h3><p>FollowPath 返回失败，或者 <code>map -&gt; base_link</code> 在 <code>progress_timeout</code> 内没有产生至少 <code>progress_min_translation</code> 的位移，都会触发轻量恢复。</p><h3 id="_8-3-轻量恢复的实际动作" tabindex="-1">8.3 轻量恢复的实际动作 <a class="header-anchor" href="#_8-3-轻量恢复的实际动作" aria-label="Permalink to &quot;8.3 轻量恢复的实际动作&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>取消 ComputePath／SmoothPath／FollowPath</span></span>\n<span class="line"><span>→ 连续发布 3 帧零速度</span></span>\n<span class="line"><span>→ clear_entirely_local_costmap</span></span>\n<span class="line"><span>→ clear_entirely_global_costmap</span></span>\n<span class="line"><span>→ 非阻塞等待 Costmap 重新填充</span></span>\n<span class="line"><span>→ 从当前 TF 重新规划</span></span></code></pre></div><p>它没有 Spin、BackUp 和 Behavior Wait，也不保证能从所有局部困境中脱困。它解决的是地图观测污染、旧路径失效和短时控制失败，不是完整的机动恢复策略。</p><h3 id="_8-4-定位超时与跳变" tabindex="-1">8.4 定位超时与跳变 <a class="header-anchor" href="#_8-4-定位超时与跳变" aria-label="Permalink to &quot;8.4 定位超时与跳变&quot;">​</a></h3><p>定位暂时丢失时，节点先停车而不是盲目沿旧路径运动。定位恢复后还要经过稳定窗口。</p><p>相邻监控周期若出现超过阈值的平移或旋转跳变，则立即废弃旧路径并重新规划。这里使用的是外部自研 <code>map -&gt; base_link</code>，没有 odom 兜底，因此定位质量直接决定规划控制安全边界。</p><h2 id="九、速度为什么分成三段" tabindex="-1">九、速度为什么分成三段 <a class="header-anchor" href="#九、速度为什么分成三段" aria-label="Permalink to &quot;九、速度为什么分成三段&quot;">​</a></h2><p>Controller Server 的 <code>cmd_vel</code> 在 Launch 中被重映射为 <code>/cmd_vel_nav</code>。</p><p>Velocity Smoother 订阅 <code>/cmd_vel_nav</code>，根据最大速度、最小速度、加速度和减速度限制，输出 <code>/cmd_vel</code>。当前配置为 OPEN_LOOP，不订阅 odom，而是使用上一周期输出作为平滑起点。</p><p><code>controlpub</code> 再把 <code>/cmd_vel</code> 转发或转换到 <code>/control_to_uart</code>。</p><p>这个拆分带来三个控制点：</p><ul><li>Controller 只负责算理想速度。</li><li>Velocity Smoother 负责速度连续性和超时停车。</li><li><code>controlpub</code> 负责适配真实底盘协议。</li></ul><p>规控节点的停车指令直接写入 <code>/cmd_vel_nav</code>，因此仍会经过 Velocity Smoother。若安全需求要求立即硬停车，还需要结合底盘协议评估平滑器减速度和 UART 超时，而不能只看上层已经发布零速度。</p><h2 id="十、源码怎样按职责拆开" tabindex="-1">十、源码怎样按职责拆开 <a class="header-anchor" href="#十、源码怎样按职责拆开" aria-label="Permalink to &quot;十、源码怎样按职责拆开&quot;">​</a></h2><p>当前实现保持一个 <code>RegulatedNavigator</code> 状态所有者，但把函数按调用阶段拆到不同编译单元。</p><h3 id="_10-1-regulated-navigator-cpp" tabindex="-1">10.1 <code>regulated_navigator.cpp</code> <a class="header-anchor" href="#_10-1-regulated-navigator-cpp" aria-label="Permalink to &quot;10.1 `regulated_navigator.cpp`&quot;">​</a></h3><ul><li>参数声明。</li><li>Action、Topic、Service、TF 和定时器创建。</li><li>Lifecycle 配置、激活、停用和清理。</li></ul><h3 id="_10-2-navigator-goal-handler-cpp" tabindex="-1">10.2 <code>navigator_goal_handler.cpp</code> <a class="header-anchor" href="#_10-2-navigator-goal-handler-cpp" aria-label="Permalink to &quot;10.2 `navigator_goal_handler.cpp`&quot;">​</a></h3><ul><li>单点、多点 Goal 校验。</li><li>取消请求。</li><li>Topic 目标。</li><li>标准导航反馈。</li></ul><h3 id="_10-3-navigator-planning-cpp" tabindex="-1">10.3 <code>navigator_planning.cpp</code> <a class="header-anchor" href="#_10-3-navigator-planning-cpp" aria-label="Permalink to &quot;10.3 `navigator_planning.cpp`&quot;">​</a></h3><ul><li>依赖等待。</li><li>ComputePath 请求。</li><li>SmoothPath 请求。</li><li>原始路径回退。</li></ul><h3 id="_10-4-navigator-control-cpp" tabindex="-1">10.4 <code>navigator_control.cpp</code> <a class="header-anchor" href="#_10-4-navigator-control-cpp" aria-label="Permalink to &quot;10.4 `navigator_control.cpp`&quot;">​</a></h3><ul><li>FollowPath 下发。</li><li>控制反馈和结果。</li><li>三帧零速度停车。</li></ul><h3 id="_10-5-navigator-monitor-cpp" tabindex="-1">10.5 <code>navigator_monitor.cpp</code> <a class="header-anchor" href="#_10-5-navigator-monitor-cpp" aria-label="Permalink to &quot;10.5 `navigator_monitor.cpp`&quot;">​</a></h3><ul><li>200 ms 任务监控。</li><li>TF 超时和跳变。</li><li>真实运动进展。</li><li>周期重规划。</li><li>清图恢复入口。</li></ul><h3 id="_10-6-navigator-task-manager-cpp" tabindex="-1">10.6 <code>navigator_task_manager.cpp</code> <a class="header-anchor" href="#_10-6-navigator-task-manager-cpp" aria-label="Permalink to &quot;10.6 `navigator_task_manager.cpp`&quot;">​</a></h3><ul><li>子 Goal 取消。</li><li>抢占、成功、失败和任务重置。</li></ul><p>这种拆分没有把状态分散到多个对象。所有编译单元仍操作同一个 <code>NavigationTask</code>，能够避免跨节点状态同步再次变成新的复杂度来源。</p><h2 id="十一、这套架构适合什么-不适合什么" tabindex="-1">十一、这套架构适合什么，不适合什么 <a class="header-anchor" href="#十一、这套架构适合什么-不适合什么" aria-label="Permalink to &quot;十一、这套架构适合什么，不适合什么&quot;">​</a></h2><h3 id="_11-1-适用场景" tabindex="-1">11.1 适用场景 <a class="header-anchor" href="#_11-1-适用场景" aria-label="Permalink to &quot;11.1 适用场景&quot;">​</a></h3><ul><li>导航流程固定，希望执行路径可预测。</li><li>已有自研定位，直接提供 <code>map -&gt; base_link</code>。</li><li>不需要运行时更换行为树 XML。</li><li>希望减少 BT 插件、黑板和 Behavior Server 的集成成本。</li><li>愿意用 C++ 状态机明确维护每一条异常分支。</li></ul><h3 id="_11-2-不适用场景" tabindex="-1">11.2 不适用场景 <a class="header-anchor" href="#_11-2-不适用场景" aria-label="Permalink to &quot;11.2 不适用场景&quot;">​</a></h3><ul><li>需要大量任务级行为动态组合。</li><li>需要到点拍照、等待、充电等 Waypoint Task Executor。</li><li>需要 Spin、BackUp 等完整恢复动作轮换。</li><li>产品侧频繁调整导航策略，但不希望重新编译 C++。</li></ul><p>取消行为树并不会自动让系统更简单。它只是把复杂度从 XML、Tick 和黑板，转移到了状态、异步回调、取消语义和恢复边界。</p><p>真正可靠的自研规控层，至少必须回答四个问题：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>当前任务属于谁？</span></span>\n<span class="line"><span>旧回调为什么不能覆盖新任务？</span></span>\n<span class="line"><span>定位异常时怎样保证停车？</span></span>\n<span class="line"><span>每一种失败最终怎样收口？</span></span></code></pre></div><p><code>nav2_regulated_modules</code> 的核心价值，不是“少启动了几个节点”，而是把这四个问题写成了可以逐行审计的确定性代码。</p>',182)])])}const P=e(h,[["render",_]]);export{f as __pageData,P as default};
